"""Write ontology/RULES.md: every rule with its source section and policy text, for a human review.

Run:  uv run python scripts/export_rules_table.py   (re-run after changing the ontology or the rules)
"""

import re

from mortgage_assistant.ingest.io import load_sections
from mortgage_assistant.rules.engine import ONTOLOGY_DIR, rule_metadata


def main() -> None:
    sections = {s.id: s for s in load_sections()}
    rules_text = "\n".join(p.read_text(encoding="utf-8") for p in sorted((ONTOLOGY_DIR / "rules").glob("*.dlog")))
    lines = [
        "# Policy rules (generated by scripts/export_rules_table.py; do not edit by hand)",
        "",
        "Every rule the rule engine (RDFox) checks, with the section it comes from. **Please review each row against "
        "the PDF.** The logic is in `ontology/rules/*.dlog`, the limits (LTV norms, which collateral allows "
        "interest-only, ...) are data in `ontology/rabo_mortgage.ttl`.",
        "",
        "Outcomes: ❌ violated · 🔍 only via Explain · ❓ missing fact · ✅ checked OK",
        "",
        "| # | Rule | What it checks | Source | Page | Outcomes it can give | Policy text (NL) |",
        "|---|---|---|---|---|---|---|",
    ]
    for i, (rid, m) in enumerate(sorted(rule_metadata().items(), key=lambda kv: (kv[1]["source"], kv[0])), start=1):
        sec = sections.get(m["source"])
        page = ", ".join(map(str, sec.pages)) if sec else ""
        where = f"{m['source']} {sec.title if sec else ''}".strip()
        outcomes = [icon for pred, icon in (("violates", "❌"), ("needsExplain", "🔍"), ("missingFact", "❓"),
                                            ("checked", "✅"))
                    if re.search(rf"rabo:{pred}, rabo:{rid}\b", rules_text)]
        text = (m.get("definition_nl") or "").replace("|", "/")
        lines.append(f"| {i} | `{rid}` | {m['label']} | {where} | {page} | {' '.join(outcomes)} | {text} |")
    lines += ["", "**Not covered (yet):** income and the affordability test (I/L-toets), BKR, residence permits, "
              "NHG-specific rules, energy-label budget (1.2.2), new-build conditions, most of the Beheerbeleid. "
              "Questions about these are answered by GraphRAG, not by the rule engine."]
    out = ONTOLOGY_DIR / "RULES.md"
    out.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"{len(rule_metadata())} rules -> {out}")


if __name__ == "__main__":
    main()
